public void handleOrderConfirmed(OrderConfirmedEvent event) {
    String orderId = event.getOrderId();

    // Idempotency check
    if (emailAlreadySent(orderId)) {
        return; // already processed, skip
    }

    sendConfirmationEmail(orderId);
    markEmailSent(orderId);
}

